insert into finlab.exam_bank(module_id,bank_version,variant,public_questions,private_questions)
select b.module_id,3,b.variant,case when b.module_id='m3' then jsonb_set(replace(b.public_questions::text,'-b2-','-b3-')::jsonb,'{4}',p.public_question) else replace(b.public_questions::text,'-b2-','-b3-')::jsonb end,case when b.module_id='m3' then jsonb_set(replace(b.private_questions::text,'-b2-','-b3-')::jsonb,'{4}',p.private_question) else replace(b.private_questions::text,'-b2-','-b3-')::jsonb end from finlab.exam_bank b join patches p on p.variant=b.variant where b.bank_version=2 on conflict(module_id,bank_version,variant) do nothing;
